#include "independent_profiles.hpp"
int main(){std::vector<std::string>words{"Z","J","OZ","OJ","ZZ","ZJ","JJ","JOZ"};std::vector<P>rows{{0,0,-1,0,1,0,0,1,0},{0,0,-1,-2,1,0,1,0,0},{0,0,0,0,2,0,0,2,0},{0,0,0,-2,2,0,2,0,0},{0,0,-1,0,3,-2,0,3,0},{0,0,-1,-4,3,-2,2,-1,2},{0,0,0,-2,2,0,1,0,2},{2,0,-1,-2,3,0,3,0,0}};int inputs=0,positive=0,continuations=0;for(int n=2;n<=4;++n)for(unsigned code=0;code<(1u<<(n*(n-1)/2));++code){G a=graph(n,code);for(int root=0;root<n;++root){P p=profile(a,root);++inputs;positive+=p[1]>0;for(int w=0;w<8;++w){G b=a;int r=root;P expected=p;for(char op:words[w]){int oldn=b.size();expected=transfer(expected,op,oldn);b=move(b,r,op);if(op=='J')r=oldn;}P actual=profile(b,r);need(actual==expected,"literal full-state continuation");I delta=0;for(int i=0;i<9;++i)delta+=rows[w][i]*p[i];need(actual[0]+actual[3]-p[0]-p[3]==delta,"literal observation row");need(actual[1]==p[1],"physical nontrivial start preservation");++continuations;}}}
G singleton{0};P p=profile(singleton,0);G z=move(singleton,0,'Z');P q=profile(z,0);need(p[1]==1&&q[1]==0,"singleton Z hostile");std::cout<<"{\"status\":\"PASS\",\"nontrivial_marked_inputs\":"<<inputs<<",\"positive_start_marked_inputs\":"<<positive<<",\"literal_eight_word_continuations\":"<<continuations<<",\"maximum_output_order\":7,\"singleton_Z_exception_checked\":true}\n";}
